// ─── Construit le payload CRM universel ──────────────────────────
const p = $input.item.json;
const crmName = $env.CRM_NAME || 'hubspot'; // hubspot | pipedrive | notion | custom

// Tags enrichis
const tags = [
  ...(p.tags || []),
  `score-${p.profile_score}`,
  p.platform,
  p.status,
  p.icp_match ? 'icp-match' : null,
  p.decision_maker ? 'decision-maker' : null
].filter(Boolean);

// Notes enrichies
const notes = [
  p.public_fact ? `📌 Fait public : ${p.public_fact}` : null,
  p.best_angle ? `🎯 Angle : ${p.best_angle}` : null,
  p.conv_summary ? `💬 Dernier échange : ${p.conv_summary}` : null,
  p.likely_pain_points?.length ? `⚡ Pain points : ${p.likely_pain_points.join(', ')}` : null,
  `Importé depuis automation LinkedIn/Instagram le ${new Date().toLocaleDateString('fr-FR')}`
].filter(Boolean).join('\n');

// Payload HubSpot
const hubspotPayload = {
  properties: {
    firstname: p.first_name,
    lastname: p.last_name || '',
    email: p.email || '',
    phone: p.phone || '',
    company: p.company || '',
    jobtitle: p.title || '',
    industry: p.industry || '',
    city: p.location || '',
    hs_lead_status: p.status === 'converted' ? 'QUALIFIED' : 'IN_PROGRESS',
    lifecyclestage: p.status === 'converted' ? 'opportunity' : 'lead',
    hs_analytics_source: 'SOCIAL_MEDIA',
    notes_last_updated: new Date().toISOString(),
    description: notes,
    linkedin_bio: p.linkedin_url || '',
    website: p.linkedin_url || '',
    // Champs personnalisés
    profile_score: String(p.profile_score),
    automation_platform: p.platform,
    automation_status: p.status,
    automation_tags: tags.join(';')
  }
};

// Payload Pipedrive
const pipedrivePayload = {
  name: p.full_name,
  email: [{ value: p.email || '', primary: true }],
  phone: [{ value: p.phone || '', primary: true }],
  org_name: p.company || '',
  job_title: p.title || '',
  label: p.status === 'converted' ? 1 : 2,
  notes_count: 1,
  visible_to: '3'
};

// Payload Notion
const notionPayload = {
  parent: { database_id: $env.NOTION_DB_ID || '' },
  properties: {
    Name: { title: [{ text: { content: p.full_name || '' } }] },
    Email: { email: p.email || null },
    Company: { rich_text: [{ text: { content: p.company || '' } }] },
    Title: { rich_text: [{ text: { content: p.title || '' } }] },
    Score: { number: p.profile_score },
    Status: { select: { name: p.status } },
    Platform: { select: { name: p.platform } },
    Tags: { multi_select: tags.slice(0,5).map(t => ({ name: t })) },
    Notes: { rich_text: [{ text: { content: notes.substring(0, 2000) } }] },
    LinkedIn: { url: p.linkedin_url || null },
    'Exporté le': { date: { start: new Date().toISOString() } }
  }
};

const payloads = { hubspot: hubspotPayload, pipedrive: pipedrivePayload, notion: notionPayload };
const endpoints = {
  hubspot: 'https://api.hubapi.com/crm/v3/objects/contacts',
  pipedrive: `https://api.pipedrive.com/v1/persons?api_token=${$env.PIPEDRIVE_API_KEY || ''}`,
  notion: 'https://api.notion.com/v1/pages',
  custom: $env.CRM_WEBHOOK_URL || ''
};

return [{
  json: {
    prospect_id: p.id,
    prospect_uuid: p.uuid,
    full_name: p.full_name,
    score: p.profile_score,
    status: p.status,
    crm_name: crmName,
    endpoint: endpoints[crmName] || endpoints.custom,
    payload: payloads[crmName] || hubspotPayload,
    notes
  }
}];

// ─── Parse réponse CRM et prépare INSERT crm_sync ────────────────
const input = $input.item.json;
const crmResponse = input;

// Extraire l'ID CRM selon le format de réponse
const crmContactId = crmResponse?.id || crmResponse?.data?.id || crmResponse?.results?.[0]?.id || null;
const crmUrl = crmResponse?.properties?.hs_object_id
  ? `https://app.hubspot.com/contacts/${$env.HUBSPOT_PORTAL_ID}/contact/${crmResponse.properties.hs_object_id}`
  : null;

// Récupérer les données du nœud précédent
const buildNode = $('Build payload CRM').item.json;
const status = crmContactId ? 'synced' : (crmResponse?.status >= 400 ? 'failed' : 'synced');

return [{
  json: {
    prospect_id: buildNode.prospect_id,
    crm_name: buildNode.crm_name,
    crm_contact_id: crmContactId,
    crm_url: crmUrl,
    status,
    score_at_export: buildNode.score,
    payload_json: JSON.stringify(buildNode.payload),
    crm_response_json: JSON.stringify(crmResponse),
    error_message: status === 'failed' ? JSON.stringify(crmResponse).substring(0, 500) : null
  }
}];

// ─── Résumé batch pour Discord ───────────────────────────────────
const results = $input.all().map(i => i.json);
const synced = results.filter(r => r.status === 'synced').length;
const failed = results.filter(r => r.status === 'failed').length;
const buildItems = $('Build payload CRM').all().map(i => i.json);

if (synced === 0 && failed === 0) return [];

const leadList = buildItems.slice(0,5)
  .map(b => `• **${b.full_name}** — Score ${b.score}/10 (${b.status})`)
  .join('\n');

return [{
  json: {
    embeds: [{
      title: `📤 Export CRM terminé`,
      description: `**${synced}** contact(s) exporté(s) vers **${buildItems[0]?.crm_name?.toUpperCase() || 'CRM'}**${failed > 0 ? `\n⚠️ ${failed} échec(s)` : ''}`,
      color: synced > 0 ? 3066993 : 15158332,
      fields: [
        { name: '🎯 Leads exportés', value: leadList || '_Aucun_', inline: false },
        { name: '✅ Succès', value: String(synced), inline: true },
        { name: '❌ Échecs', value: String(failed), inline: true }
      ],
      footer: { text: `CRM Export • ${new Date().toLocaleDateString('fr-FR')}` },
      timestamp: new Date().toISOString()
    }]
  }
}];
